function stack(setName,cols){
  const set=sec.children.find(c=>c.name===setName&&c.type==='COMPONENT_SET');
  if(!set) return null;
  const items=set.children;
  const GAP=12;
  let colW=[],rowH=[];
  items.forEach((c,i)=>{const col=i%cols, row=Math.floor(i/cols); colW[col]=Math.max(colW[col]||0,c.width); rowH[row]=Math.max(rowH[row]||0,c.height);});
  let x=0;
  items.forEach((c,i)=>{
    const col=i%cols,row=Math.floor(i/cols);
    c.x=colW.slice(0,col).reduce((a,b)=>a+b+GAP,0);
    c.y=rowH.slice(0,row).reduce((a,b)=>a+b+GAP,0);
  });
  const w=colW.reduce((a,b)=>a+b+GAP,0)-GAP;
  const h=rowH.reduce((a,b)=>a+b+GAP,0)-GAP;
  set.resize(w,h);
  return [Math.round(w),Math.round(h)];
}

